import React, { useEffect, useRef, useState, useCallback } from 'react';
import { createChart } from 'lightweight-charts';
import DebugSnapshot from '../DebugSnapshot/DebugSnapshot';
import styles from './TradingChart.module.css';

const formatPrice = (price, market) => {
  if (market === 'BTC' || market === 'ETH') {
    return price.toFixed(2);
  } else {
    return price.toFixed(2);
  }
};

const TradingChart = ({ candles, signal, position, supports, resistances, orderBlocks, hasCredits = false, showAnalysis = false, potentialEntry = null }) => {
  const chartContainerRef = useRef(null);
  const chartRef = useRef(null);
  const candleSeriesRef = useRef(null);
  const priceLines = useRef([]);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [dataError, setDataError] = useState(null);
  const isInitialized = useRef(false);

  const clearPriceLines = useCallback(() => {
    if (candleSeriesRef.current && priceLines.current.length > 0) {
      priceLines.current.forEach(line => {
        try {
          candleSeriesRef.current.removePriceLine(line);
        } catch (e) {}
      });
      priceLines.current = [];
    }
  }, []);

  useEffect(() => {
    if (candles && candles.error) {
      setDataError(candles.message || 'Données insuffisantes');
      return;
    }

    if (!Array.isArray(candles) || candles.length < 300) {
      setDataError(`Données insuffisantes: ${Array.isArray(candles) ? candles.length : 0} bougies (minimum 300 requis)`);
      return;
    }

    setDataError(null);
  }, [candles]);

  useEffect(() => {
    if (!chartContainerRef.current) return;
    if (dataError) return;
    if (!Array.isArray(candles) || candles.length === 0) return;

    const chart = createChart(chartContainerRef.current, {
      layout: {
        background: { color: '#1a1a1a' },
        textColor: '#d1d4dc',
      },
      grid: {
        vertLines: { color: '#2b2b2b' },
        horzLines: { color: '#2b2b2b' },
      },
      width: chartContainerRef.current.clientWidth,
      height: isFullscreen ? window.innerHeight - 100 : 320,
      rightPriceScale: {
        borderColor: '#3a3a3a',
      },
      timeScale: {
        borderColor: '#3a3a3a',
        rightOffset: 80,
        barSpacing: 15,
        timeVisible: true,
        secondsVisible: false,
      },
      handleScroll: {
        mouseWheel: true,
        pressedMouseMove: true,
        horzTouchDrag: true,
        vertTouchDrag: true,
      },
      handleScale: {
        axisPressedMouseMove: true,
        mouseWheel: true,
        pinch: true,
      },
      crosshair: {
        mode: 1,
        vertLine: {
          width: 1,
          color: '#758696',
          style: 3,
        },
        horzLine: {
          width: 1,
          color: '#758696',
          style: 3,
        },
      },
    });

    const candleSeries = chart.addCandlestickSeries({
      upColor: '#26a69a',
      downColor: '#ef5350',
      borderVisible: false,
      wickUpColor: '#26a69a',
      wickDownColor: '#ef5350',
    });

    candleSeries.setData(candles);
    isInitialized.current = true;

    setTimeout(() => {
      try {
        if (chart && chart.timeScale) {
          chart.timeScale().fitContent();
        }
      } catch (e) {}
    }, 100);

    chartRef.current = chart;
    candleSeriesRef.current = candleSeries;

    const handleResize = () => {
      if (chartRef.current && chartContainerRef.current) {
        try {
          chartRef.current.applyOptions({
            width: chartContainerRef.current.clientWidth,
            height: isFullscreen ? window.innerHeight - 100 : 320,
          });
        } catch (e) {}
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      if (chartRef.current) {
        try {
          chartRef.current.remove();
        } catch (e) {}
        chartRef.current = null;
        candleSeriesRef.current = null;
        isInitialized.current = false;
      }
    };
  }, [isFullscreen, dataError]);

  useEffect(() => {
    if (!candleSeriesRef.current || !Array.isArray(candles) || candles.length === 0 || dataError) return;
    if (!isInitialized.current) return;

    try {
      const lastCandle = candles[candles.length - 1];
      candleSeriesRef.current.update(lastCandle);
    } catch (e) {
      console.warn('Chart update error:', e);
    }
  }, [candles, dataError]);

  useEffect(() => {
    if (!candleSeriesRef.current) return;

    clearPriceLines();

    if (position && position.status === 'OPEN') {
      const isLong = position.direction === 'LONG';

      console.log('📊 [TradingChart] LECTURE POSITION (PAS de recalcul):', {
        id: position.id,
        market: position.market,
        direction: position.direction,
        entry: formatPrice(position.entry_price, position.market),
        sl: formatPrice(position.stop_loss, position.market),
        tp1: formatPrice(position.take_profit_1, position.market),
        pnl: position.pnl?.toFixed(2) || '0.00',
        debugSnapshot: position.debugSnapshot
      });

      const lineEntry = candleSeriesRef.current.createPriceLine({
        price: position.entry_price,
        color: isLong ? '#26a69a' : '#ef5350',
        lineWidth: 3,
        lineStyle: 0,
        axisLabelVisible: true,
        title: `${isLong ? '🟢 LONG ↑' : '🔴 SHORT ↓'} - ${formatPrice(position.entry_price, position.market)}`,
      });

      const distanceToSL = isLong
        ? ((position.entry_price - position.stop_loss) / position.entry_price * 100)
        : ((position.stop_loss - position.entry_price) / position.entry_price * 100);

      const lineSL = candleSeriesRef.current.createPriceLine({
        price: position.stop_loss,
        color: '#ff1744',
        lineWidth: 4,
        lineStyle: 0,
        axisLabelVisible: true,
        title: `🛑 STOP LOSS - ${formatPrice(position.stop_loss, position.market)} (-${distanceToSL.toFixed(2)}%)`,
      });

      const gainTP1 = isLong
        ? ((position.take_profit_1 - position.entry_price) / position.entry_price * 100)
        : ((position.entry_price - position.take_profit_1) / position.entry_price * 100);

      const lineTP1 = candleSeriesRef.current.createPriceLine({
        price: position.take_profit_1,
        color: '#00e676',
        lineWidth: 4,
        lineStyle: 0,
        axisLabelVisible: true,
        title: `🎯 TP1 - ${formatPrice(position.take_profit_1, position.market)} (+${gainTP1.toFixed(2)}%)`,
      });

      priceLines.current.push(lineEntry, lineSL, lineTP1);

      if (position.take_profit_2) {
        const gainTP2 = isLong
          ? ((position.take_profit_2 - position.entry_price) / position.entry_price * 100)
          : ((position.entry_price - position.take_profit_2) / position.entry_price * 100);

        const lineTP2 = candleSeriesRef.current.createPriceLine({
          price: position.take_profit_2,
          color: '#00e676',
          lineWidth: 3,
          lineStyle: 2,
          axisLabelVisible: true,
          title: `🎯 TP2 - ${formatPrice(position.take_profit_2, position.market)} (+${gainTP2.toFixed(2)}%)`,
        });
        priceLines.current.push(lineTP2);
      }
    }
    else if (signal && signal.status === 'ACTIVE') {
      const entryPrice = (signal.entry_min + signal.entry_max) / 2;

      const correctDirection = signal.take_profit_1 > entryPrice ? 'LONG' : 'SHORT';
      const isLong = correctDirection === 'LONG';

      if (signal.direction !== correctDirection) {
        console.warn('⚠️ DIRECTION INCORRECTE DÉTECTÉE ET CORRIGÉE', {
          signalDirection: signal.direction,
          correctDirection,
          entry: formatPrice(entryPrice, signal.market),
          tp1: formatPrice(signal.take_profit_1, signal.market),
          sl: formatPrice(signal.stop_loss, signal.market)
        });
      }

      console.log('📊 CHART DRAWING SIGNAL:', {
        direction: correctDirection,
        entry: formatPrice(entryPrice, signal.market),
        sl: formatPrice(signal.stop_loss, signal.market),
        tp1: formatPrice(signal.take_profit_1, signal.market),
        tp2: signal.take_profit_2 ? formatPrice(signal.take_profit_2, signal.market) : 'N/A',
        isLong,
        validation: isLong
          ? `TP1(${formatPrice(signal.take_profit_1, signal.market)}) > Entry(${formatPrice(entryPrice, signal.market)}) > SL(${formatPrice(signal.stop_loss, signal.market)})`
          : `SL(${formatPrice(signal.stop_loss, signal.market)}) > Entry(${formatPrice(entryPrice, signal.market)}) > TP1(${formatPrice(signal.take_profit_1, signal.market)})`
      });

      const lineEntry = candleSeriesRef.current.createPriceLine({
        price: entryPrice,
        color: isLong ? '#26a69a' : '#ef5350',
        lineWidth: 3,
        lineStyle: 0,
        axisLabelVisible: true,
        title: `${isLong ? '🟢 LONG ↑' : '🔴 SHORT ↓'} - ${formatPrice(entryPrice, signal.market)}`,
      });

      const signalDistanceToSL = isLong
        ? ((entryPrice - signal.stop_loss) / entryPrice * 100)
        : ((signal.stop_loss - entryPrice) / entryPrice * 100);

      const lineSL = candleSeriesRef.current.createPriceLine({
        price: signal.stop_loss,
        color: '#ff1744',
        lineWidth: 4,
        lineStyle: 0,
        axisLabelVisible: true,
        title: `🛑 STOP LOSS - ${formatPrice(signal.stop_loss, signal.market)} (-${signalDistanceToSL.toFixed(2)}%)`,
      });

      const signalGainTP1 = isLong
        ? ((signal.take_profit_1 - entryPrice) / entryPrice * 100)
        : ((entryPrice - signal.take_profit_1) / entryPrice * 100);

      const lineTP1 = candleSeriesRef.current.createPriceLine({
        price: signal.take_profit_1,
        color: '#00e676',
        lineWidth: 4,
        lineStyle: 0,
        axisLabelVisible: true,
        title: `🎯 TP1 - ${formatPrice(signal.take_profit_1, signal.market)} (+${signalGainTP1.toFixed(2)}%)`,
      });

      priceLines.current.push(lineEntry, lineSL, lineTP1);

      if (signal.take_profit_2) {
        const signalGainTP2 = isLong
          ? ((signal.take_profit_2 - entryPrice) / entryPrice * 100)
          : ((entryPrice - signal.take_profit_2) / entryPrice * 100);

        const lineTP2 = candleSeriesRef.current.createPriceLine({
          price: signal.take_profit_2,
          color: '#00e676',
          lineWidth: 3,
          lineStyle: 2,
          axisLabelVisible: true,
          title: `🎯 TP2 - ${formatPrice(signal.take_profit_2, signal.market)} (+${signalGainTP2.toFixed(2)}%)`,
        });
        priceLines.current.push(lineTP2);
      }
    }
    else if (potentialEntry) {
      const entryPrice = (potentialEntry.entry_min + potentialEntry.entry_max) / 2;
      const correctDirection = potentialEntry.take_profit_1 > entryPrice ? 'LONG' : 'SHORT';
      const isLong = correctDirection === 'LONG';

      console.log('📍 GRAPHIQUE - ZONE D\'ENTRÉE POTENTIELLE:', {
        direction: correctDirection,
        entry: formatPrice(entryPrice, potentialEntry.market),
        sl: formatPrice(potentialEntry.stop_loss, potentialEntry.market),
        tp1: formatPrice(potentialEntry.take_profit_1, potentialEntry.market)
      });

      const lineEntry = candleSeriesRef.current.createPriceLine({
        price: entryPrice,
        color: isLong ? '#26a69a' : '#ef5350',
        lineWidth: 3,
        lineStyle: 2,
        axisLabelVisible: true,
        title: `${isLong ? '🟢 ZONE ENTRÉE LONG ↑' : '🔴 ZONE ENTRÉE SHORT ↓'} - ${formatPrice(entryPrice, potentialEntry.market)}`,
      });

      const lineSL = candleSeriesRef.current.createPriceLine({
        price: potentialEntry.stop_loss,
        color: '#ff1744',
        lineWidth: 2,
        lineStyle: 2,
        axisLabelVisible: true,
        title: `🛑 SL - ${formatPrice(potentialEntry.stop_loss, potentialEntry.market)}`,
      });

      const lineTP1 = candleSeriesRef.current.createPriceLine({
        price: potentialEntry.take_profit_1,
        color: '#00e676',
        lineWidth: 2,
        lineStyle: 2,
        axisLabelVisible: true,
        title: `🎯 TP1 - ${formatPrice(potentialEntry.take_profit_1, potentialEntry.market)}`,
      });

      priceLines.current.push(lineEntry, lineSL, lineTP1);

      if (potentialEntry.take_profit_2) {
        const lineTP2 = candleSeriesRef.current.createPriceLine({
          price: potentialEntry.take_profit_2,
          color: '#00e676',
          lineWidth: 2,
          lineStyle: 3,
          axisLabelVisible: true,
          title: `🎯 TP2 - ${formatPrice(potentialEntry.take_profit_2, potentialEntry.market)}`,
        });
        priceLines.current.push(lineTP2);
      }
    }
    else if (showAnalysis) {
      if (supports && supports.length > 0) {
        const topSupports = supports.slice(0, 2);
        topSupports.forEach((support, idx) => {
          const line = candleSeriesRef.current.createPriceLine({
            price: support,
            color: '#4caf50',
            lineWidth: 1,
            lineStyle: 2,
            axisLabelVisible: true,
            title: `S${idx + 1}`,
          });
          priceLines.current.push(line);
        });
      }

      if (resistances && resistances.length > 0) {
        const topResistances = resistances.slice(0, 2);
        topResistances.forEach((resistance, idx) => {
          const line = candleSeriesRef.current.createPriceLine({
            price: resistance,
            color: '#f44336',
            lineWidth: 1,
            lineStyle: 2,
            axisLabelVisible: true,
            title: `R${idx + 1}`,
          });
          priceLines.current.push(line);
        });
      }

      if (orderBlocks) {
        if (orderBlocks.bullish && orderBlocks.bullish.length > 0) {
          const block = orderBlocks.bullish[0];
          const lineHigh = candleSeriesRef.current.createPriceLine({
            price: block.high,
            color: '#26a69a',
            lineWidth: 1,
            lineStyle: 3,
            axisLabelVisible: false,
            title: '',
          });
          const lineLow = candleSeriesRef.current.createPriceLine({
            price: block.low,
            color: '#26a69a',
            lineWidth: 1,
            lineStyle: 3,
            axisLabelVisible: false,
            title: '',
          });
          priceLines.current.push(lineHigh, lineLow);
        }

        if (orderBlocks.bearish && orderBlocks.bearish.length > 0) {
          const block = orderBlocks.bearish[0];
          const lineHigh = candleSeriesRef.current.createPriceLine({
            price: block.high,
            color: '#ef5350',
            lineWidth: 1,
            lineStyle: 3,
            axisLabelVisible: false,
            title: '',
          });
          const lineLow = candleSeriesRef.current.createPriceLine({
            price: block.low,
            color: '#ef5350',
            lineWidth: 1,
            lineStyle: 3,
            axisLabelVisible: false,
            title: '',
          });
          priceLines.current.push(lineHigh, lineLow);
        }
      }
    }
  }, [signal, position, supports, resistances, orderBlocks, showAnalysis, potentialEntry, clearPriceLines]);

  const toggleFullscreen = () => {
    setIsFullscreen(!isFullscreen);
  };

  const recenter = () => {
    if (chartRef.current) {
      chartRef.current.timeScale().fitContent();
    }
  };

  if (dataError) {
    return (
      <div className={`${styles.chartWrapper}`}>
        <div className={styles.dataErrorOverlay}>
          <div className={styles.dataErrorMessage}>
            <h3>Données insuffisantes</h3>
            <p>{dataError}</p>
            <p className={styles.dataErrorHint}>
              Le graphique nécessite au minimum 300 bougies pour s'afficher correctement.
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`${styles.chartWrapper} ${isFullscreen ? styles.fullscreen : ''}`}>
      {!hasCredits && (
        <div className={styles.noCreditsOverlay}>
          <div className={styles.noCreditsMessage}>
            <h3>🔒 Crédits requis</h3>
            <p>Rechargez votre compte pour accéder aux analyses et recevoir des signaux</p>
          </div>
        </div>
      )}
      <div className={styles.chartControls}>
        <button onClick={recenter} className={styles.controlBtn}>
          Recentrer
        </button>
        <button onClick={toggleFullscreen} className={styles.controlBtn}>
          {isFullscreen ? 'Quitter plein écran' : 'Plein écran'}
        </button>
      </div>
      <div ref={chartContainerRef} className={styles.chartContainer} />
      {position && position.debugSnapshot && (
        <DebugSnapshot data={position.debugSnapshot} location="CHART" />
      )}
    </div>
  );
};

export default TradingChart;
